CREATE TABLE "agent_pull_request_requesters" (
  "state" TEXT NOT NULL CHECK("state" IN ('opened', 'pending')),
  "pr_key" TEXT NOT NULL,
  "user_id" TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  "recorded_at" INTEGER NOT NULL,
  PRIMARY KEY ("state", "pr_key", "user_id")
);
CREATE INDEX idx_agent_pull_request_requesters_user ON agent_pull_request_requesters (user_id);

CREATE TABLE "environment_slot_leases" (
  "block" INTEGER NOT NULL,
  "first_port" INTEGER NOT NULL,
  "size" INTEGER NOT NULL,
  "workspace_id" TEXT NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
  "space_id" TEXT NOT NULL,
  "definition_id" TEXT NOT NULL,
  "pool_key" TEXT NULL,
  "pool_slot" INTEGER NULL,
  "created_at" INTEGER NOT NULL,
  PRIMARY KEY ("block"),
  UNIQUE ("pool_key", "pool_slot"),
  UNIQUE ("workspace_id", "space_id", "definition_id")
);

CREATE TABLE "invite_secure_routes" (
  "route_id" TEXT NOT NULL,
  "code_hash" TEXT NOT NULL,
  "workspace_id" TEXT NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
  PRIMARY KEY ("route_id")
);
CREATE INDEX idx_invite_secure_routes_workspace ON invite_secure_routes (workspace_id);

CREATE TABLE "jobs" (
  "id" TEXT NOT NULL,
  "workspace_id" TEXT NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
  "kind" TEXT NOT NULL CHECK("kind" IN ('agentRun', 'pipelineStep', 'codeIndex', 'goldenRender', 'benchmark', 'evalBatch')),
  "spec_json" TEXT NOT NULL DEFAULT '{}' CHECK(json_valid("spec_json") AND json_type("spec_json") = 'object'),
  "required_caps_json" TEXT NOT NULL DEFAULT '[]' CHECK(json_valid("required_caps_json") AND json_type("required_caps_json") = 'array'),
  "preferred_caps_json" TEXT NOT NULL DEFAULT '[]' CHECK(json_valid("preferred_caps_json") AND json_type("preferred_caps_json") = 'array'),
  "status" TEXT NOT NULL DEFAULT 'queued' CHECK("status" IN ('queued', 'leased', 'running', 'done', 'failed', 'reaped', 'cancelled')),
  "worker_id" TEXT NULL REFERENCES workers (id) ON DELETE SET NULL,
  "pinned_worker_id" TEXT NULL,
  "lease_expires_at" INTEGER NULL,
  "priority" INTEGER NOT NULL DEFAULT 0,
  "submitted_by" TEXT NULL REFERENCES users (id) ON DELETE SET NULL,
  "cost_micros" INTEGER NOT NULL DEFAULT 0,
  "attempts" INTEGER NOT NULL DEFAULT 0,
  "max_attempts" INTEGER NOT NULL DEFAULT 1,
  "last_acked_seq" INTEGER NOT NULL DEFAULT 0,
  "result_json" TEXT NULL CHECK(json_valid("result_json")),
  "error" TEXT NULL,
  "agent_id" TEXT NULL,
  "conversation_id" TEXT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  "leased_at" INTEGER NULL,
  "started_at" INTEGER NULL,
  "finished_at" INTEGER NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX idx_jobs_lease_expiry ON jobs (lease_expires_at);
CREATE INDEX idx_jobs_status_finished ON jobs (status, finished_at);
CREATE INDEX idx_jobs_submitted_by ON jobs (submitted_by);
CREATE INDEX idx_jobs_worker_status ON jobs (worker_id, status);
CREATE INDEX idx_jobs_workspace_status ON jobs (workspace_id, status);

CREATE TABLE "managed_action_policies" (
  "id" TEXT NOT NULL,
  "action_class" TEXT NULL CHECK("action_class" IN ('fileDelete', 'fileWriteOutsideWorktree', 'gitCommit', 'gitPush', 'prCreate', 'prPublish', 'vendorSyncWrite', 'networkEgress', 'secretAccess', 'packageInstall', 'processSpawn', 'workspaceMutation', 'enclosureControl', 'hostExecution')),
  "command_prefix" TEXT NULL,
  "decision" TEXT NOT NULL DEFAULT 'prompt' CHECK("decision" IN ('allow', 'prompt', 'deny')),
  "enforcement" TEXT NULL CHECK("enforcement" IN ('advisory', 'soft', 'hard')),
  "constraint_json" TEXT NULL CHECK(json_valid("constraint_json") AND json_type("constraint_json") = 'object'),
  "updated_by" TEXT NULL REFERENCES users (id) ON DELETE SET NULL,
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  PRIMARY KEY ("id"),
  CHECK ((action_class IS NULL) <> (command_prefix IS NULL))
);
CREATE INDEX idx_managed_action_policies_updated_by ON managed_action_policies (updated_by);
CREATE UNIQUE INDEX uq_managed_action_policies_class ON managed_action_policies (action_class) WHERE action_class IS NOT NULL;
CREATE UNIQUE INDEX uq_managed_action_policies_command ON managed_action_policies (command_prefix) WHERE command_prefix IS NOT NULL;

CREATE TABLE "paired_devices" (
  "id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  "landing_workspace_id" TEXT NULL REFERENCES workspaces (id) ON DELETE SET NULL,
  "label" TEXT NOT NULL,
  "platform" TEXT NOT NULL DEFAULT 'web',
  "psk_ref" TEXT NOT NULL,
  "remote_fingerprint" TEXT NULL,
  "status" TEXT NOT NULL DEFAULT 'pendingConfirm' CHECK("status" IN ('pendingConfirm', 'active', 'revoked')),
  "paired_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  "last_seen_at" INTEGER NULL,
  "expires_at" INTEGER NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX idx_paired_devices_landing_workspace ON paired_devices (landing_workspace_id);
CREATE INDEX idx_paired_devices_user ON paired_devices (user_id);

CREATE TABLE "placement_log" (
  "id" TEXT NOT NULL,
  "workspace_id" TEXT NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
  "job_id" TEXT NOT NULL REFERENCES jobs (id) ON DELETE CASCADE,
  "worker_id" TEXT NULL REFERENCES workers (id) ON DELETE SET NULL,
  "decision" TEXT NOT NULL DEFAULT 'queued' CHECK("decision" IN ('pinned', 'preferred', 'spill', 'queued', 'no_capable_worker', 'cache_warming', 'reaped', 'retried', 'pinned_worker_unavailable')),
  "reason" TEXT NOT NULL DEFAULT '',
  "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)),
  PRIMARY KEY ("id")
);
CREATE INDEX idx_placement_log_created ON placement_log (created_at);
CREATE INDEX idx_placement_log_job ON placement_log (job_id);
CREATE INDEX idx_placement_log_worker ON placement_log (worker_id);
CREATE INDEX idx_placement_log_workspace ON placement_log (workspace_id);

